write_file {"path": "clean_build.py", "content": "#!/usr/bin/env python3
import os
import shutil
import sys

def clean_directory(dirpath):
    """Delete all contents of dirpath but keep the directory."""
    if not os.path.isdir(dirpath):
        print(f"Error: {dirpath} is not a directory", file=sys.stderr)
        sys.exit(1)
    for item in os.listdir(dirpath):
        full = os.path.join(dirpath, item)
        try:
            if os.path.isfile(full) or os.path.islink(full):
                os.remove(full)
            elif os.path.isdir(full):
                shutil.rmtree(full)
            else:
                print(f"Warning: unknown item {full}", file=sys.stderr)
        except Exception as e:
            print(f"Error deleting {full}: {e}", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    build_path = "build"
    clean_directory(build_path)
    print(f"Cleaned {build_path}")"}

