write_file {"path": "compute_totals.py", "content": "import csv
import os
from collections import defaultdict

csv_path = os.path.join(os.path.dirname(__file__), 'data/invoices.csv')
totals = defaultdict(float)

try:
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            customer = row.get('customer', '').strip()
            amount = row.get('amount', '').strip()
            if customer and amount:
                try:
                    totals[customer] += float(amount)
                except ValueError:
                    print(f"Invalid amount '{amount}' for customer '{customer}'")
except FileNotFoundError:
    print(f"File not found: {csv_path}")
    exit(1)
except Exception as e:
    print(f"Error reading CSV: {e}")
    exit(1)

print("Total billed per customer:")
for customer, total in sorted(totals.items()):
    print(f"{customer}: {total:.2f}")"}

